<?php defined( 'ABSPATH' ) || exit; $show_billing = 'invoice' === $type || 'yes' === LHIWC_Settings::get( 'packing_billing' ); $show_shipping = 'packing-slip' === $type || 'yes' === LHIWC_Settings::get( 'shipping_address' ); ?>
<section class="lhiwc-addresses"><?php if ( $show_billing && $document['billing']['formatted'] ) : ?><div><h3><?php esc_html_e( 'Billing address', 'lightweight-html-invoices-for-woocommerce' ); ?></h3><address><?php echo nl2br( esc_html( $document['billing']['formatted'] ) ); ?></address><?php if ( 'invoice' === $type && 'yes' === LHIWC_Settings::get( 'billing_email' ) && $document['billing']['email'] ) : ?><p><?php echo esc_html( $document['billing']['email'] ); ?></p><?php endif; ?><?php if ( 'invoice' === $type && 'yes' === LHIWC_Settings::get( 'billing_phone' ) && $document['billing']['phone'] ) : ?><p><strong><?php esc_html_e( 'Phone:', 'lightweight-html-invoices-for-woocommerce' ); ?></strong> <?php echo esc_html( $document['billing']['phone'] ); ?></p><?php endif; ?></div><?php endif; ?><?php if ( $show_shipping && $document['shipping']['formatted'] ) : ?><div><h3><?php esc_html_e( 'Shipping address', 'lightweight-html-invoices-for-woocommerce' ); ?></h3><address><?php echo nl2br( esc_html( $document['shipping']['formatted'] ) ); ?></address><?php if ( $document['shipping']['phone'] && ( 'invoice' === $type || 'yes' === LHIWC_Settings::get( 'packing_phone' ) ) ) : ?><p><strong><?php esc_html_e( 'Mobile:', 'lightweight-html-invoices-for-woocommerce' ); ?></strong> <?php echo esc_html( $document['shipping']['phone'] ); ?></p><?php endif; ?></div><?php endif; ?></section>
